options.spec:
params:
  wclick: { select: single }
plot:
  - mark: areaY
    data: { from: weather, filterBy: $wclick }
    x: { dateMonth: date }
    y1: { max: temp_max }
    y2: { min: temp_min }
    fill: '#ccc'
    fillOpacity: 0.25
    curve: monotone-x
  - mark: areaY
    data: { from: weather, filterBy: $wclick }
    x: { dateMonth: date }
    y1: { avg: temp_max }
    y2: { avg: temp_min }
    fill: '#FF9830'
    fillOpacity: 0.75
    curve: monotone-x
xTickFormat: '%b'
yDomain: [-10, 40]
xLabel: null
yLabel: ↑ °C

params:
  acategory: { select: intersect }
  aquery: { select: intersect, include: $acategory }
  ahover: { select: intersect, empty: true }

plot:
  - mark: barX
    data: { from: athletes, filterBy: $aquery }
    x: { sum: medals }
    y: nationality
    fill: '#FADE2A'
    sort: { y: -x, limit: 15 }
xLabel: Medals →
yLabel: null
marginLeft: 45

params:
  acategory: { select: intersect }
  aquery: { select: intersect, include: $acategory }
  ahover: { select: intersect, empty: true }

input: table
from: athletes
filterBy: $aquery
as: $ahover
columns: [name, nationality, sex, height, weight, sport, gold, silver, bronze]
